const OPERATING: OperatingSubstep[] = ["industry", "business_type", "profile"];
const PREPARATION: PreparationSubstep[] = ["brand", "website", "data", "connections", "ai_reporting", "workspace", "review"];
const PROVIDERS = [{ id:"google_workspace", label:"Google Workspace" }, { id:"microsoft_365", label:"Microsoft 365" }, { id:"apple_icloud", label:"Apple / iCloud" }] as const;
