function blankProfile(name:string):Profile{return{businessName:name,tradingName:"",abn:"",websiteUrl:"",phone:"",email:"",primaryContactName:"",description:"",services:"",targetCustomers:"",differentiators:"",challenges:"",logoUrl:"",iconUrl:""}}
