function recommendations(industry?:string){const growth:Record<string,string[]>={property:["prospecting","ai-visibility","seo","automation","analytics","reviews"],finance:["prospecting","ai-visibility","automation","analytics","reviews"],services:["prospecting","seo","automation","analytics","reviews"],"accommodation-hospitality":["marketing","ai-visibility","seo","analytics","social","reviews"],automotive:["marketing","prospecting","seo","analytics","social","reviews"],"creator-media":["marketing","ai-visibility","analytics","social"]};const workflows:Record<string,string[]>={property:["Lead → appraisal/listing follow-up","Vendor and buyer nurture","Review request after completion"],finance:["Lead → discovery → application follow-up","Document collection reminders","Client review and re-engagement"],services:["Enquiry → quote → job follow-up","Missed-call and quote follow-up","Review request after job completion"],"accommodation-hospitality":["Enquiry → direct booking follow-up","Pre-arrival and post-stay messaging","Review and return-guest nurture"],automotive:["Enquiry → appointment/test drive follow-up","Service reminders","Review request after delivery/service"],"creator-media":["Audience capture and nurture","Campaign/release follow-up","Partnership pipeline reminders"]};const dashboard:Record<string,string[]>={property:["Listings & pipeline","Lead sources","Vendor/buyer activity"],finance:["Applications & pipeline","Lead conversion","Settlement/revenue outlook"],services:["Quotes & jobs","Lead conversion","Team/service activity"],"accommodation-hospitality":["Bookings & occupancy","Direct demand","Guest/review activity"],automotive:["Enquiries & deals","Appointments","Inventory/service activity"],"creator-media":["Audience growth","Campaign performance","Revenue opportunities"]};return{growth:growth[industry??""]??["marketing","analytics","reviews"],workflows:workflows[industry??""]??["Lead capture and follow-up","Customer nurture","Review and re-engagement"],dashboard:dashboard[industry??""]??["Lead pipeline","Growth performance","Business health"]}}
function suggestedAidaPriorities(industry:string,goals:string[],rec:ReturnType<typeof recommendations>){const goalLabels=GEN2_GOAL_OPTIONS.filter(g=>goals.includes(g.id)).map(g=>g.label);const advice=[...goalLabels,...rec.workflows].filter(Boolean).slice(0,5);const reporting=[...rec.dashboard,...goalLabels.map(g=>`${g} progress`)].filter(Boolean).slice(0,5);return{advice,reporting}}
function appIdsForTemplates(templates:string[]){return [...new Set(INDUSTRY_TAXONOMY.flatMap(g=>g.subIndustries).filter(s=>templates.includes(s.id)).map(s=>s.appId))]}
function displayApp(id:string){return id.split("-").map(v=>v.charAt(0).toUpperCase()+v.slice(1)).join(" ")}
function displayGrowthApp(id:string){if(id==="growth_suite")return"Growth Suite";return GROWTH_APP_CATALOGUE.find(a=>a.appId===id)?.label?.replace("DigitalGate ","")??displayApp(id)}
function displayTemplate(id:string){return INDUSTRY_TAXONOMY.flatMap(g=>g.subIndustries).find(s=>s.id===id)?.name??displayApp(id)}
function friendlyCheckoutError(message?:string){const clean=message?.trim();if(!clean||/could not start subscription checkout/i.test(clean)||/couldn't start subscription checkout/i.test(clean))return"We couldn’t open secure payment setup. Your setup is saved. Please try again, or contact DigitalGate if this continues.";return clean}
function operatorRequestHeaders(id?:string):Record<string,string>{return id?{"X-DG-Operator-Organisation":id}:{}}

