 async function patch(body:Record<string,unknown>){setSaving(true);setError(null);try{if(reviewMode&&operatorTargetOrganisationId){const local=body.progress&&typeof body.progress==="object"?body.progress as Partial<Gen2OnboardingProgress>:{};const step=typeof body.markStepComplete==="string"?body.markStepComplete as Gen2OnboardingStep:undefined;const next={...progress,...local,completedSteps:step?[...new Set([...(progress.completedSteps??[]),step])]:progress.completedSteps};setProgress(next);setMessage("Rehearsal only — these changes are not saved to the customer.");return next}const r=await fetch("/api/v1/onboarding/gen2",{method:"PATCH",headers:{"Content-Type":"application/json",...operatorRequestHeaders(operatorTargetOrganisationId)},body:JSON.stringify(body)});const j=await r.json().catch(()=>({}));if(!r.ok){setError(j.error?.message||"Could not save setup");return null}if(j.data?.progress)setProgress(j.data.progress);return j.data?.progress as Gen2OnboardingProgress|undefined}finally{setSaving(false)}}async function mark(step:Gen2OnboardingStep,extra:Record<string,unknown>={}){return patch({markStepComplete:step,...extra})}
 function setPrimaryIndustry(id:string){const recommendation=recommendations(id);setOperating(o=>({...o,primaryIndustry:id,secondaryIndustries:(o.secondaryIndustries??[]).filter(x=>x!==id),recommendedGrowthApps:recommendation.growth,recommendedWorkflows:recommendation.workflows,recommendedDashboard:recommendation.dashboard}));if(!progress.premiumApps?.length)setProgress(p=>({...p,premiumApps:["growth_suite"]}));setTemplates(current=>current.filter(t=>INDUSTRY_TAXONOMY.find(g=>g.id===id)?.subIndustries.some(s=>s.id===t)))}function toggleSecondary(id:string){setOperating(o=>{const c=o.secondaryIndustries??[];return{...o,secondaryIndustries:c.includes(id)?c.filter(x=>x!==id):[...c,id]}})}function toggleTemplate(id:string){setTemplates(c=>c.includes(id)?c.filter(x=>x!==id):[...c,id])}function toggleGoal(id:string){setGoals(c=>c.includes(id)?c.filter(x=>x!==id):[...c,id])}function toggleGrowth(id:string){if(offer)return;setProgress(p=>({...p,premiumApps:(p.premiumApps??[]).includes(id)?(p.premiumApps??[]).filter(x=>x!==id):[...(p.premiumApps??[]),id]}))}function toggleGrowthSuite(){if(offer)return;setProgress(p=>({...p,premiumApps:(p.premiumApps??[]).includes("growth_suite")?[]:["growth_suite"]}));setShowGrowthApps(false)}function customiseGrowthSuite(){if(offer)return;const allIndividual=GROWTH_APP_CATALOGUE.filter(a=>!a.included).map(a=>a.appId);setProgress(p=>({...p,premiumApps:allIndividual}));setShowGrowthApps(true)}function chooseProvider(id:string){setSetup(s=>({...s,connections:Object.fromEntries(PROVIDERS.map(p=>[p.id,{requested:p.id===id,requestedCapabilities:p.id===id?["contacts","calendar","mail"]:[],status:p.id===id?"planned":"not_started"}])) as Gen2VipSetup["connections"]}));setShowProviders(false)}
 async function searchBusinessName(){const name=(profile.tradingName||profile.businessName).trim();if(name.length<2){setError("Enter a business name to search.");return}setBusinessSearching(true);setError(null);setMessage(null);try{const r=await fetch(`/api/v1/business-identity/abn?name=${encodeURIComponent(name)}`);const j=await r.json().catch(()=>({}));const matches=(j.data?.matches??[]) as AbrNameMatch[];if(!r.ok){setError(j.data?.abr?.message||j.error?.message||"Business search failed.");setBusinessMatches([]);return}setBusinessMatches(matches);if(!matches.length)setMessage("No matching Australian businesses found.");}finally{setBusinessSearching(false)}}
